import{_ as a,o as i,c as o,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Lei de Garantia Médica","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0044-医疗保障法.md","filePath":"pt/0044-医疗保障法.md"}'),t={name:"pt/0044-医疗保障法.md"};function s(r,e,n,c,l,m){return i(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="lei-de-garantia-medica" tabindex="-1">Lei de Garantia Médica <a class="header-anchor" href="#lei-de-garantia-medica" aria-label="Permalink to &quot;Lei de Garantia Médica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>44</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Direito Médico, Medicina Simbiótica, Tratamento de Lesões de Cultivo, Saúde da Vida, Sistema de Seguro Saúde</td></tr></tbody></table><h2 id="i-objetivo-legislativo-e-principios-fundamentais" tabindex="-1">I. Objetivo Legislativo e Princípios Fundamentais <a class="header-anchor" href="#i-objetivo-legislativo-e-principios-fundamentais" aria-label="Permalink to &quot;I. Objetivo Legislativo e Princípios Fundamentais&quot;">​</a></h2><p>A 《Lei de Garantia Médica》 é uma das cinco leis complementares da civilização simbiótica de âncoras, visando garantir o direito à saúde e o direito médico de todos os seres dentro de Hengyuanzhou, estabelecer um sistema médico simbiótico que cubra todas as raças, e assegurar que cada ser possa receber tratamento oportuno e eficaz quando doente ou ferido.</p><p>Esta lei estabelece os seguintes princípios fundamentais:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Prioridade à Saúde</td><td>A saúde da vida é a base de toda evolução, o Estado e a civilização colocam a garantia da saúde da vida em posição prioritária</td></tr><tr><td>Princípio da Cobertura Universal</td><td>A garantia médica cobre todos os seres, independentemente de raça, nível de cultivo, origem e situação econômica</td></tr><tr><td>Princípio do Diagnóstico Hierárquico</td><td>Estabelecer sistema de diagnóstico de três níveis: atenção primária, médica regional, médica avançada, distribuir recursos médicos de forma racional</td></tr><tr><td>Princípio da Combinação de Prevenção e Tratamento</td><td>Prevenção como principal, combinar prevenção e tratamento, valorizar a prevenção e reabilitação de lesões de cultivo</td></tr><tr><td>Princípio da Adaptação Inter-Racial</td><td>Fornecer planos médicos adaptados às características fisiológicas de diferentes raças, proibir o uso de um único padrão humano</td></tr><tr><td>Princípio do Caráter de Bem Público</td><td>Os serviços médicos básicos têm caráter de bem público, não se pode privar o direito ao tratamento da vida com fins lucrativos</td></tr></tbody></table><h2 id="ii-garantia-juridica-do-direito-a-saude-da-vida" tabindex="-1">II. Garantia Jurídica do Direito à Saúde da Vida <a class="header-anchor" href="#ii-garantia-juridica-do-direito-a-saude-da-vida" aria-label="Permalink to &quot;II. Garantia Jurídica do Direito à Saúde da Vida&quot;">​</a></h2><p>Esta lei estabelece claramente que o direito à saúde da vida é um direito fundamental concedido a cada ser pela Constituição Simbiótica, incluindo especificamente:</p><ol><li><strong>Direito Médico Básico</strong>: Cada ser tem o direito de receber serviços médicos básicos gratuitos, incluindo diagnóstico e tratamento de doenças comuns, medicamentos básicos, exames de saúde de rotina, etc.</li><li><strong>Direito ao Tratamento de Emergência</strong>: Cada ser tem o direito de receber tratamento de emergência quando sofre doença ou lesão súbita, e as instituições médicas não podem recusar o tratamento de emergência por qualquer motivo.</li><li><strong>Direito ao Tratamento de Lesões de Cultivo</strong>: Os cultivadores que sofrem lesões como distúrbio de energia, lesão de meridianos, desvio de cultivo, etc. durante o processo de cultivo têm o direito de receber tratamento profissional.</li><li><strong>Direito ao Consentimento Informado</strong>: O paciente tem o direito de conhecer sua própria condição, plano de tratamento, riscos e prognóstico, e tem o direito de escolher ou recusar o plano de tratamento.</li><li><strong>Direito à Proteção da Privacidade</strong>: As informações médicas e os dados corporais do paciente são protegidos por lei, não podem ser divulgados ou usados para outros fins sem o consentimento do paciente.</li><li><strong>Direito à Garantia de Reabilitação</strong>: Os pacientes doentes ou feridos têm o direito de receber tratamento de reabilitação e aparelhos auxiliares, ajudando-os a recuperar a capacidade de trabalho e de vida.</li></ol><h2 id="iii-estrutura-do-sistema-medico-simbiotico" tabindex="-1">III. Estrutura do Sistema Médico Simbiótico <a class="header-anchor" href="#iii-estrutura-do-sistema-medico-simbiotico" aria-label="Permalink to &quot;III. Estrutura do Sistema Médico Simbiótico&quot;">​</a></h2><p>O sistema médico da civilização simbiótica de âncoras é dividido em três níveis, com mecanismos de encaminhamento e colaboração estabelecidos entre os níveis:</p><table tabindex="0"><thead><tr><th>Nível</th><th>Nome</th><th>Função</th><th>Área de Cobertura</th></tr></thead><tbody><tr><td>Primeiro nível</td><td>Posto de Saúde Primário</td><td>Diagnóstico e tratamento de doenças comuns, prevenção e cuidados de saúde, exames básicos, transporte de emergência</td><td>Comunidade/vila/plano pequeno</td></tr><tr><td>Segundo nível</td><td>Centro Médico Regional</td><td>Diagnóstico especializado, tratamento cirúrgico, tratamento inicial de lesões de cultivo, reabilitação</td><td>Cidade/região/plano médio</td></tr><tr><td>Terceiro nível</td><td>Hospital Geral Médico Avançado</td><td>Doenças graves e complexas, lesões de cultivo avançadas, doenças do domínio da consciência, doenças complexas inter-raciais</td><td>Núcleo da civilização/plano grande</td></tr></tbody></table><p>Além disso, foi estabelecida a &quot;Especialidade de Lesões de Cultivo&quot;: trata especificamente de vários tipos de lesões durante o processo de cultivo, incluindo sobrecarga de energia, ruptura de meridianos, invasão de demônios internos, trauma da alma, etc., equipada com pessoal médico proficiente nas leis de cultivo.</p><h2 id="iv-fundo-de-garantia-medica" tabindex="-1">IV. Fundo de Garantia Médica <a class="header-anchor" href="#iv-fundo-de-garantia-medica" aria-label="Permalink to &quot;IV. Fundo de Garantia Médica&quot;">​</a></h2><p>O fundo de garantia médica é a base econômica para o funcionamento do sistema médico simbiótico, e suas fontes incluem:</p><ul><li>Alocação de acumulação pública (fonte principal)</li><li>Retenção de garantia médica no mecanismo de contrato de produção conjunta</li><li>Doações sociais</li><li>Receita de investimento do fundo</li></ul><p>O escopo de pagamento do fundo inclui: despesas com serviços médicos básicos, despesas de emergência, despesas de tratamento de lesões de cultivo, despesas com medicamentos básicos, despesas de reabilitação, etc. O paciente individual só precisa pagar uma pequena taxa de copagamento, e isenções são concedidas para pessoas com dificuldades financeiras.</p><h2 id="v-instituicoes-medicas-e-pessoal-medico" tabindex="-1">V. Instituições Médicas e Pessoal Médico <a class="header-anchor" href="#v-instituicoes-medicas-e-pessoal-medico" aria-label="Permalink to &quot;V. Instituições Médicas e Pessoal Médico&quot;">​</a></h2><ul><li><strong>Instituições Médicas Públicas</strong>: Estabelecidas pelo Estado ou pela comunidade da civilização, responsáveis por serviços médicos básicos e funções de saúde pública, com financiamento garantido pelo fundo de garantia médica.</li><li><strong>Instituições Médicas Privadas</strong>: Estabelecidas por forças sociais de acordo com a lei, podem fornecer serviços médicos de alta qualidade, mas devem aceitar a supervisão do departamento competente de saúde, e não podem recusar pacientes de emergência.</li><li><strong>Instituições Médicas Inter-Raciais</strong>: Instituições médicas especializadas estabelecidas para as necessidades fisiológicas de raças especiais, equipadas com pessoal médico de outras raças.</li><li><strong>Direitos e Deveres do Pessoal Médico</strong>: O pessoal médico desfruta de direitos como proteção profissional, remuneração razoável, formação profissional, etc., e ao mesmo tempo tem o dever de salvar vidas, respeitar os pacientes, manter sigilo médico, etc.</li></ul><h2 id="vi-saude-publica-e-prevencao" tabindex="-1">VI. Saúde Pública e Prevenção <a class="header-anchor" href="#vi-saude-publica-e-prevencao" aria-label="Permalink to &quot;VI. Saúde Pública e Prevenção&quot;">​</a></h2><p>O Estado estabelece um sistema de saúde pública, cumprindo as seguintes funções:</p><ol><li>Monitoramento e prevenção e controle de doenças infecciosas, estabelecimento de mecanismo de alerta de epidemia inter-planos.</li><li>Exames de saúde universais e gerenciamento de registros de saúde.</li><li>Promoção da segurança do cultivo e orientação de prevenção de lesões de cultivo.</li><li>Supervisão da saúde ambiental e segurança de alimentos e medicamentos.</li><li>Resposta de emergência a eventos de saúde pública súbitos.</li></ol><h2 id="vii-responsabilidade-juridica" tabindex="-1">VII. Responsabilidade Jurídica <a class="header-anchor" href="#vii-responsabilidade-juridica" aria-label="Permalink to &quot;VII. Responsabilidade Jurídica&quot;">​</a></h2><p>Atividades que violam as disposições desta lei assumem as seguintes responsabilidades de acordo com a gravidade da infração:</p><ul><li>Instituições médicas que recusam pacientes de emergência, ordenar a correção e impor multa, em casos de consequências graves revogar a licença de exercício.</li><li>Pessoal médico que causa danos ao paciente por negligência grave, assumir responsabilidade por indenização, em casos graves revogar a qualificação profissional.</li><li>Instituições médicas que cobram taxas ilegais ou realizam tratamento excessivo, ordenar o reembolso das taxas e impor multa.</li><li>Divulgar a privacidade médica do paciente, assumir indenização por danos morais, em casos graves追究 responsabilidade criminal.</li><li>Produzir ou vender medicamentos falsificados ou de baixa qualidade, confiscar os ganhos ilegais e impor multa, se constituir crime追究 responsabilidade criminal.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Lei de Garantia Médica》 é a manifestação do conceito de &quot;todos têm um caminho&quot; da civilização simbiótica de âncoras no campo da saúde. Ao estabelecer um sistema de garantia médica de cobertura universal, criar a especialidade de lesões de cultivo e garantir o direito ao tratamento de emergência, ela assegura que cada ser possa receber tratamento oportuno quando doente ou ferido, consolidando a base de saúde para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>38-共生医疗体系 (Sistema Médico Simbiótico)</li><li>45-住房保障法 (Lei de Garantia de Habitação)</li><li>08-人人有路保障体系 (Sistema de Garantia de que Todos Têm um Caminho)</li></ul>',29)])])}const b=a(t,[["render",s]]);export{p as __pageData,b as default};
